test('M09 onay anında kapsam: A kapsamlı HRBP, HR_ADMIN\'in doğruladığı B birimi rol dosyasını onaylayamaz; M13 yeniden kabul kapasiteye tabi; M12 taslak hedefe ACHIEVED yok', async () => {
  const t = T['VEE']!; const wb = await download(`/api/t/${t.id}/templates/org.xlsx`, 'hr-VEE'); for (const sh of ['Birim_Tipleri', 'Birimler', 'Hiyerarsiler', 'Iliskiler']) fillSheet(wb, sh, [], true); fillSheet(wb, 'Org_Rolleri', [{ tenant_code: t.code, operation: 'CREATE', role_code: 'ROLE_B1_LEAD', unit_code: 'B1', title: 'Ekip Lideri', permission_profile: 'ACTION_OWNER', valid_from: '2026-01-01' }], true);
  const v = await upload(`/api/t/${t.id}/imports/org`, 'hr-VEE', await toBuf(wb)); assert.equal(v.body.state, 'validated', JSON.stringify(v.body.issues));
  const byA = await api('POST', `/api/t/${t.id}/imports/${v.body.jobId}/commit`, {}, 'hrbp-v'); assert.equal(byA.status, 403, 'M09: profil yeterli (ACTION_OWNER verebilir) ama B1 kapsam dışı → 403: ' + JSON.stringify(byA.body)); assert.equal(byA.body.error, 'unit_not_in_scope');
  assert.equal((await api('POST', `/api/t/${t.id}/imports/${v.body.jobId}/commit`, {}, 'hr-VEE')).status, 200);
  // M13: B1'de kapasite: mevcut aktif hedef 1 (GUV-01); ikinci hedef GUR-01 açılır; üçüncü olarak taslağa düşen bir hedefin yeniden kabulü limitte reddedilmeli
  const b1 = t.units!['B1']!; const t2 = await api('POST', `/api/t/${t.id}/cycles/${t.cycle}/units/${b1}/targets`, { itemCode: 'GUR-01' }, 'b1v'); assert.equal(t2.status, 200, JSON.stringify(t2.body));
  const list = (await api('GET', `/api/t/${t.id}/cycles/${t.cycle}/units/${b1}/targets`, undefined, 'b1v')).body as unknown as { id: string; status: string; item_code: string }[]; assert.equal(list.filter(x => ['accepted', 'active'].includes(x.status)).length, 2);
  const third = await api('POST', `/api/t/${t.id}/cycles/${t.cycle}/units/${b1}/targets`, { itemCode: 'BAG-03' }, 'b1v'); assert.ok(third.status !== 200, 'üçüncü hedef açılmaz: ' + JSON.stringify(third.body)); const cnt = ((await api('GET', `/api/t/${t.id}/cycles/${t.cycle}/units/${b1}/targets`, undefined, 'b1v')).body as unknown as { status: string }[]).filter(x => ['accepted', 'active', 'under_review', 'pending_acceptance'].includes(x.status)).length; assert.equal(cnt, 2, 'kapasite: en fazla 2 yer tutan hedef');
  // düzeltme: B1 GUV-01 başlangıcı değişir → hedef under_review; rebase → pending_acceptance; kabul kapasite kilidinde (diğer 1 aktif + taslak = sınır içinde → 200); ikinci taslak olsaydı 409
  const corr = await resultsWb(t, { mode: 'PATCH', only: ['B1|GUV-01_TB'], alt: true }); assert.equal(corr.body.state, 'validated', JSON.stringify(corr.body.issues)); const cc = await api('POST', `/api/t/${t.id}/imports/${corr.body.jobId}/commit`, {}, 'hr-VEE'); assert.equal(cc.status, 200); assert.ok(((cc.body.applied as { targetsUnderReview: number }).targetsUnderReview) >= 1, 'M14: yalnız etkilenen hedef incelemeye');
  const g = list.find(x => x.item_code === 'GUV-01')!; const rb = await api('POST', `/api/t/${t.id}/targets/${g.id}/review`, { decision: 'accept', reason: 'düzeltilmiş başlangıç', baseline: 'rebase' }, 'hr-VEE'); assert.equal(rb.status, 200, JSON.stringify(rb.body)); assert.equal(rb.body.status, 'pending_acceptance');
  // M12: taslak hedefe takip → NOT_COMMITTED (gözlem var, ACHIEVED yok)
  const cyc2 = await api('POST', `/api/t/${t.id}/cycles`, { code: '2027-ANA', name: '2027', periodStart: '2027-04-05', periodEnd: '2027-04-23', instrumentVersionId: t.iv }, 'hr-VEE'); assert.equal(cyc2.status, 200, JSON.stringify(cyc2.body));
  const t27 = { id: t.id, code: t.code, cycle: cyc2.body.id as string }; const wb27 = await download(`/api/t/${t.id}/templates/results.xlsx?cycleId=${t27.cycle}`, 'hr-VEE'); const ws = wb27.getWorksheet('Sonuclar')!, dws = wb27.getWorksheet('Dagilimlar')!; const seen = new Map<string, Record<string, number>>();
  ws.eachRow((row, n) => { if (n === 1) return; const unit = String(row.getCell(3).value), mc = String(row.getCell(4).value); if (unit !== 'B1') return; const item = mc.replace(/_(TB|NPS)$/, ''); let d = seen.get(item); if (!d) { d = item === 'BAG-03' ? { '0': 1, '7': 4, '9': 5, '10': 10 } : { '1': 1, '2': 1, '3': 2, '4': 8, '5': 8 }; seen.set(item, d); } const nn = 20; const val = mc.endsWith('_NPS') ? Math.round((((d['9'] ?? 0) + (d['10'] ?? 0) - (d['0'] ?? 0)) / nn) * 1000) / 10 : item === 'BAG-03' ? Math.round((((d['9'] ?? 0) + (d['10'] ?? 0)) / nn) * 1000) / 10 : Math.round((((d['4'] ?? 0) + (d['5'] ?? 0)) / nn) * 1000) / 10; row.getCell(5).value = 'OBSERVED'; row.getCell(6).value = nn; row.getCell(7).value = String(val).replace('.', ','); for (const [o, c] of Object.entries(d)) dws.addRow([t.code, '2027-ANA', unit, mc, o, c]); });
  const up27 = await upload(`/api/t/${t.id}/imports/results?cycleId=${t27.cycle}`, 'hr-VEE', await toBuf(wb27)); assert.equal(up27.body.state, 'validated', JSON.stringify((up27.body.issues as unknown[]).slice(0, 3))); assert.equal((await api('POST', `/api/t/${t.id}/imports/${up27.body.jobId}/commit`, {}, 'hr-VEE')).status, 200);
  const fu = await api('GET', `/api/t/${t.id}/targets/${g.id}/followup?cycleId=${t27.cycle}`, undefined, 'hr-VEE'); assert.equal(fu.status, 200, JSON.stringify(fu.body)); assert.equal(fu.body.status, 'NOT_COMMITTED', 'M12: kabul edilmemiş hedefe kesin ulaşma yok: ' + JSON.stringify(fu.body)); assert.ok(fu.body.observed, 'gözlem ayrıca gösterilir'); assert.equal(fu.body.outcome, undefined);
  const gv = ((await api('GET', `/api/t/${t.id}/cycles/${t.cycle}/units/${b1}/targets`, undefined, 'b1v')).body as unknown as { id: string; version: number }[]).find(x => x.id === g.id)!; const acc = await api('POST', `/api/t/${t.id}/targets/${g.id}/accept`, { reason: 'kabul', expectedVersion: gv.version }, 'b1v'); assert.equal(acc.status, 200, JSON.stringify(acc.body));
  const fu2 = await api('GET', `/api/t/${t.id}/targets/${g.id}/followup?cycleId=${t27.cycle}`, undefined, 'hr-VEE'); assert.ok(fu2.body.outcome, 'kabulden sonra değerlendirme üretilir');
});
