    assert.equal((await api('POST', `/api/t/${t.id}/responsibility-map`, { itemCode: 'GUV-01', responsibilityCenter: 'line_manager', roleCode: 'ROLE_A1_YENI' }, 'hrbp-v')).status, 403, 'yalnız HR_ADMIN');
