    assert.equal((await api('POST', `/api/t/${t.id}/corporate/ambitions/${amb.body.id}/units/${t.units!['B1']}/decision`, { decision: 'exception', reason: 'kapsam dışı' }, 'ab')).status, 403, 'B1 için izleyici karar veremez');
