    const qq = (await api('GET', `/api/t/${t.id}/corporate/queue`, undefined, 'hr-VEE')).body as unknown as { id: string; kind: string }[]; const ex1 = qq.find(x => x.kind === 'decision' || x.kind === 'exception')!; assert.ok(ex1, 'karşı teklif merkezi kuyrukta'); assert.equal((await api('POST', `/api/t/${t.id}/corporate/queue/${ex1.id}/decide`, { decision: 'istisna kabul; A1 için 85 karşı teklifi onaylandı', state: 'decided', outcome: 'accept' }, 'hr-VEE')).status, 200);
