    const rc = await api('POST', `/api/t/${t.id}/corporate/ambitions/${a1.body.id}/reconcile`, {}, 'hr-VEE'); assert.equal(rc.status, 200, JSON.stringify(rc.body)); const proj0 = rc.body.contributionProjection as number | null;
