    const ct25 = await api('GET', `/api/t/${t.id}/corporate/control-tower`, undefined, 'hr-VEE'); assert.ok((ct25.body.ambitionDetail as { id: string; contributionProjection: number | null }[]).find(x => x.id === a1.body.id)!.contributionProjection === null, 'Control Tower aynı motor');
    await client.query('UPDATE survey_cycle SET confidentiality_threshold = 5 WHERE tenant_id = $1 AND id = $2', [t.id, t.cycle]);
