    // P0-269-08: karşı teklif aralığı
    const u0 = (d5.body.cohort as { unit_id: string; unit_code: string }[]).find(x => x.unit_code === 'A1')!;
    for (const v of [-1, 101]) assert.equal((await api('POST', `/api/t/${t.id}/corporate/ambitions/${a1.body.id}/units/${u0.unit_id}/decision`, { decision: 'counterproposal', counterproposalValue: v, reason: 'aralık testi' }, 'hr-VEE')).status, 400, `karşı teklif ${v} reddedilir`);
    assert.equal((await api('POST', `/api/t/${t.id}/corporate/ambitions/${a1.body.id}/units/${u0.unit_id}/decision`, { decision: 'counterproposal', reason: 'değersiz' }, 'hr-VEE')).status, 422, 'değer zorunlu');
