    const qq = (await api('GET', `/api/t/${t.id}/corporate/queue`, undefined, 'hr-VEE')).body as unknown as { id: string; kind: string; entity_id: string; unit_id: string; state: string; title: string }[]; const qi = qq.find(x => x.entity_id === a1.body.id && x.unit_id === u0.unit_id)!; assert.ok(qi); assert.equal(qi.kind, 'exception', 'reopen: tür güncellendi (karşı teklif → istisna)');
    const cl = await api('POST', `/api/t/${t.id}/corporate/queue/${qi.id}/decide`, { decision: 'kapatıldı, karar yok', state: 'closed' }, 'hr-VEE'); assert.equal(cl.status, 422); assert.equal(cl.body.error, 'decision_required', 'V270-P0-01: karar gerektiren kayıt kararsız kapatılamaz');
    assert.equal((await client.query('SELECT reconciliation FROM cm_ambition_cohort WHERE tenant_id = $1 AND ambition_id = $2 AND unit_id = $3', [t.id, a1.body.id, u0.unit_id])).rows[0].reconciliation, 'exception', 'kapat kabul etmedi');
