    assert.equal((await api('POST', `/api/t/${t.id}/corporate/queue/${qi2.id}/decide`, { decision: 'sonuç belirtilmedi', state: 'decided' }, 'hr-VEE')).status, 422, 'karar gerektiren türde outcome zorunlu');
    const beforeProj = (await api('GET', `/api/t/${t.id}/corporate/ambitions/${a1.body.id}`, undefined, 'hr-VEE')).body.contributionProjection as number; const beforeCounted = ((await api('GET', `/api/t/${t.id}/corporate/ambitions/${a1.body.id}`, undefined, 'hr-VEE')).body.engine as { counted: number }).counted;
    assert.equal((await api('POST', `/api/t/${t.id}/corporate/queue/${qi2.id}/decide`, { decision: 'istisna kabul', state: 'decided', outcome: 'accept' }, 'hr-VEE')).body.effect, 'exception_accepted');
    const afterD = (await api('GET', `/api/t/${t.id}/corporate/ambitions/${a1.body.id}`, undefined, 'hr-VEE')).body; assert.equal((afterD.engine as { counted: number; excluded: number }).counted, beforeCounted - 1, 'kabul edilen istisna paydadan çıktı'); assert.ok((afterD.engine as { excluded: number }).excluded >= 1); void beforeProj;
    // kaynak isteği: kapat ≠ onay
    const rr = await api('POST', `/api/t/${t.id}/corporate/resource-requests`, { kind: 'resource', unitId: u0.unit_id, need: 'ek eğitmen', reason: 'kapasite yetersiz' }, 'hr-VEE'); assert.equal(rr.status, 200, JSON.stringify(rr.body)); const rq = ((await api('GET', `/api/t/${t.id}/corporate/queue`, undefined, 'hr-VEE')).body as unknown as { id: string; entity_id: string }[]).find(x => x.entity_id === rr.body.id)!; assert.equal((await api('POST', `/api/t/${t.id}/corporate/queue/${rq.id}/decide`, { decision: 'kapatıldı', state: 'closed' }, 'hr-VEE')).body.error, 'decision_required'); assert.ok(((await api('GET', `/api/t/${t.id}/corporate/queue`, undefined, 'hr-VEE')).body as unknown as { id: string }[]).some(x => x.id === rq.id), 'kaynak isteği kuyrukta görünür kalır'); assert.equal((await client.query('SELECT state FROM cm_resource_request WHERE tenant_id = $1 AND id = $2', [t.id, rr.body.id])).rows[0].state, 'open', 'kapat onaylamaz');
