  const vee = pf.items.find(x => x.id === t.id)!; assert.ok(vee.summary && vee.summary.counts.units > 0 && vee.summary.counts.overdueActions === null /* v2.10.0: izlenen dönem seçilmemiş şirkette döneme bağlı sayaçlar null (bütün dönemlerin toplamı gösterilmez) */ && typeof vee.summary.setup.complete === 'boolean', JSON.stringify(vee).slice(0, 200));
  // yetkisiz platform kullanıcısı durduramaz
